window.FILM_WORK_PROMPTS={"work_id":"src-918215ca041471b0","records":[{"work_id":"src-918215ca041471b0","frame_id":"FG-f67001a3f2237e73","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl006.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"昏暗室内舞台，背景悬挂巨大的红色横幅，上方印有黑色英文字样。舞台上有数个站立的人影剪影，前景是密集的观众头部轮廓，整体处于强烈的逆光环境中。","analysis":"画面采用低角度仰拍，构图以中央巨大的红色矩形背景为主，占据画面上半部。舞台上的表演者呈现为黑色剪影，仅能辨识出站立的大姿态，人物相对背景显得较小。前景观众头部形成黑色波浪状边缘，遮挡了舞台底部。光线以红色背景光为主，辅以几处刺眼的白色点状光源，明暗对比极强，细节被高光吞没。","prompt":"昏暗的室内演出场景，低角度仰拍视角。背景是一面巨大的红色矩形幕布，上方印有模糊的黑色英文文字。舞台中央及两侧分布着数个站立的人影剪影，轮廓模糊，无法辨认具体衣着。舞台前方散布着几盏明亮的白色点状灯光，形成强烈的眩光。画面底部前景是密集的观众头部黑色剪影，呈波浪状起伏，遮挡了舞台下半部分。整体画面处于高对比度的逆光环境中，红色背景光与黑色剪影形成鲜明反差，画质带有明显的颗粒感，氛围压抑且充满现场感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:58:10-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl006.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-f2130f3ca2ae6a03","origin":"visual"},{"work_id":"src-918215ca041471b0","frame_id":"FG-36f9cf16bfd2da95","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl017.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"昏暗的夜间户外集会现场，前景左侧可见两名人物紧密相拥的深色剪影，背景是密集的人群与建筑轮廓，右侧舞台区域发出强烈的白色亮光。","analysis":"画面采用低角度仰拍，前景人物仅显示头部与肩部的黑色轮廓，占据画面左下部分，面部细节完全不可见。背景人群呈点状分布，延伸至画面上方。右侧光源极亮，形成大面积过曝的白色光晕，与左侧的深黑色剪影形成强烈明暗对比。画面中部横贯一道蓝色水平光斑，整体色调由黑、白及冷蓝色块构成。","prompt":"低分辨率夜间户外集会画面，前景左侧为两名人物紧密相拥的黑色剪影，仅可见头部与肩部轮廓，面部不可辨。背景是密集且模糊的人群，延伸至画面上方，隐约可见建筑轮廓。右侧舞台区域发出极亮的白色强光，形成大面积过曝光晕，照亮周围空气。画面中部横贯一道蓝色水平光斑，整体色调由深黑、亮白及冷蓝色块构成，明暗对比强烈，氛围昏暗。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:58:16-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl017.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-b105ce94b441ead2","origin":"visual"},{"work_id":"src-918215ca041471b0","frame_id":"FG-18d8a9605e981cbb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl028.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"一条狭长且空旷的室内走廊，两侧是平整的白色墙壁，地面呈现深色反光质感。走廊尽头站着一个模糊的黑色人影，头顶上方悬挂着绿色的指示牌。","analysis":"画面采用严格的中心对称构图，利用两侧墙壁与地面的线条形成强烈的透视引导，将视线汇聚于走廊深处。人物位于画面极远处，仅呈现为微小的黑色剪影，全身轮廓可见但细节完全不可辨。整体光线偏冷，色调以灰白与深黑为主，地面反射出模糊的亮斑，营造出一种幽闭、冷清且带有压抑感的视觉氛围。","prompt":"一条狭长且空旷的室内走廊，采用中心对称构图，两侧是平整的白色墙壁，地面呈现深色反光质感，反射出模糊的亮斑。走廊尽头站着一个模糊的黑色人影，全身轮廓可见但细节不可辨，头顶上方悬挂着绿色的指示牌。整体光线偏冷，色调以灰白与深黑为主，利用两侧墙壁与地面的线条形成强烈的透视引导，营造出一种幽闭、冷清且带有压抑感的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:58:22-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl028.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-e37b84e3e572d704","origin":"visual"},{"work_id":"src-918215ca041471b0","frame_id":"FG-9dbfb56e2330439d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl039.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"黑暗背景中，一个倾斜的霓虹灯招牌占据画面主体。招牌上方有一行白色小字，下方是巨大的粉紫色“VENUS”字样，周围环绕着蓝紫色的光晕。","analysis":"画面采用仰视视角，主体为倾斜的霓虹灯牌。构图上，灯牌从左上向右下延伸，占据画面中心。背景几乎全黑，仅见零星蓝色光点。明暗对比强烈，霓虹灯是主要光源，粉紫色的“VENUS”字样与上方的白色文字在黑暗中发光，形成鲜明的色彩层次。","prompt":"这是一张低分辨率的夜景照片，主体是一个倾斜的霓虹灯招牌。背景是深邃的黑色，只有招牌发出的光亮。招牌上方有一行较小的白色霓虹文字，下方是巨大的、带有立体感的粉紫色“VENUS”字样，字体边缘有明亮的粉色光晕。招牌顶部和边缘有蓝紫色的线条装饰。画面下方和右侧散落着几个模糊的蓝色光点。整体色调以黑、紫、粉为主，呈现出一种复古的夜店或酒吧氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:58:28-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl039.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-1f6c91e43a264777","origin":"visual"},{"work_id":"src-918215ca041471b0","frame_id":"FG-91c5412bb8f00671","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl050.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"一名滑雪者背对镜头，在陡峭的雪坡上向下滑行。背景是阴沉的天空和右侧的山脊，强烈的阳光从云层中透出，照亮了部分雪面。","analysis":"画面采用低角度仰拍，滑雪者位于画面左侧，全身可见，呈站立滑行姿态，手持雪杖。人物在画面中占比适中，与广阔的天空和雪坡形成对比。右侧是连绵的山脊，天空占据画面上半部分，云层厚重。强烈的逆光从右上方云层缝隙中射出，形成明显的光晕和镜头眩光，使人物呈现剪影效果，雪面在强光下显得明亮。","prompt":"低角度仰拍视角，一名滑雪者背对镜头，全身可见，正站在倾斜的雪坡上，身体略微前倾，双手持雪杖支撑。人物穿着深色滑雪服，在强烈的逆光下呈现剪影。背景是阴沉多云的天空，右上方有强烈的阳光穿透云层，形成耀眼的光晕和镜头眩光。右侧是覆盖着积雪的山脊，延伸至远方。雪面在强光照射下显得明亮，与天空的灰暗色调形成对比。画面整体色调偏冷，带有明显的逆光效果。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:58:34-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl050.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-1596dcaf95ca8594","origin":"visual"},{"work_id":"src-918215ca041471b0","frame_id":"FG-b024374d9d314242","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl007.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"昏暗舞台中央，一名短发人物站立，怀抱吉他，身体被后方强光照亮形成剪影，前景下方可见观众头部轮廓，背景大面积黑暗。","analysis":"人物位于画面中偏右，全身轮廓可见，呈站立姿态，怀抱吉他。后方强逆光将人物边缘勾勒清晰，面部及身体正面处于阴影中。前景下方有模糊的深色头部剪影，背景左上方有微小亮点，右上方有绿色矩形亮块。整体明暗对比强烈，光色以冷白为主。","prompt":"低分辨率昏暗舞台画面，中央偏右站立一名短发人物，身穿深色短袖，怀抱吉他，身体被后方强逆光照亮形成剪影，面部细节不可辨。前景下方有模糊的深色观众头部轮廓，背景大面积黑暗，左上方有微小白色亮点，右上方有绿色矩形亮块。整体明暗对比强烈，光色冷白，人物全身轮廓清晰，环境占比大。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:20:29+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl007.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-f8c0019d9c590023","origin":"visual"},{"work_id":"src-918215ca041471b0","frame_id":"FG-756c32ad85d44acc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl018.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"一辆深色轿车行驶在宽阔的柏油公路上，路面标线清晰。道路两侧分布着茂密的树木与灌木丛，左侧设有绿色交通指示牌，天空占据画面上半部分，云层厚重且明亮。","analysis":"画面采用中心透视构图，道路向远方延伸形成视觉引导线。主体车辆位于画面中下部，呈现完整的背部轮廓，相对于广阔的天空和两侧植被显得较小。视角为平视，光线充足，天空呈现高亮度的白色与淡蓝色，地面与植被处于自然光照下，色彩层次分明，整体色调偏向写实与自然。","prompt":"这是一张低分辨率的公路行车视角画面。画面中心是一辆深色轿车，正背对镜头沿道路向前行驶，车身轮廓清晰但细节模糊。宽阔的灰色柏油路面占据画面下半部分，白色虚线车道标线向远方汇聚。道路两侧是郁郁葱葱的树木和杂草，左侧路边立有一块绿色的长方形交通指示牌。天空占据了画面的上半部分，布满了大块的白色积云，阳光透过云层洒下，整体光线明亮，色彩以天空的蓝白、植被的深绿和路面的灰色为主，呈现出开阔的户外自然环境氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:20:35+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl018.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-9542938927e5d952","origin":"visual"},{"work_id":"src-918215ca041471b0","frame_id":"FG-dfd39e1a75dc0c86","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl029.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"画面主体为广阔平坦的白色雪原，地平线横贯画面中部。上方是深蓝色天空，太阳高悬于顶部中央，发出强烈的放射状光芒，整体环境空旷寂寥。","analysis":"构图采用水平分割，地平线位于画面垂直方向约三分之二处。太阳位于顶部正中，形成强烈的星芒效果，光线呈放射状向四周扩散，在天空中形成明显的亮色光晕。下方雪原呈现大面积的灰白色调，表面有细微的起伏纹理。画面整体明暗对比强烈，上方天空深邃，下方地面明亮，色彩以冷色调的蓝白为主。","prompt":"这是一张低分辨率的户外风景静帧。画面展现了一片无边无际的白色雪原，地平线平直且清晰，将画面分为上下两部分。上方是纯净的深蓝色天空，太阳位于画面顶部正中央，发出耀眼的白光，并伴有明显的十字星芒和放射状光线，光线穿透天空形成朦胧的光晕。下方的雪原占据了画面下半部分，呈现出灰白色的质感，表面有轻微的起伏和阴影，显得寒冷而空旷。整体色调偏冷，以蓝色和白色为主，光影对比强烈，营造出一种极寒、寂静且辽阔的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:20:42+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl029.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-c12dbcc42dd69546","origin":"visual"},{"work_id":"src-918215ca041471b0","frame_id":"FG-b6fd6e55839a0ddb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl040.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"昏暗室内，人物仰面躺卧在灰白色褶皱织物上，头部位于画面中央，嘴部张开，右侧可见一只手部轮廓。","analysis":"画面采用俯视角度拍摄，主体为人物面部及颈部，占据画面中心约三分之一区域。环境由大面积灰白色织物构成，布满不规则褶皱。光线极暗，仅面部受光，形成强烈明暗对比，背景几乎隐没在黑暗中，整体色调偏冷灰。","prompt":"昏暗室内场景，俯视视角。一名人物仰面躺卧在灰白色褶皱织物上，织物占据画面大部分空间，呈现不规则起伏。人物面部位于画面中央，嘴部张开，皮肤在微弱光线下呈现苍白质感。画面右侧边缘可见一只手部轮廓，手指自然伸展。整体光线极暗，仅面部有局部照明，形成强烈的明暗对比，背景隐没在深黑色阴影中，色调冷峻压抑，低分辨率质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:20:48+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl040.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-0e8033a9108a1c76","origin":"visual"},{"work_id":"src-918215ca041471b0","frame_id":"FG-6fa6f96431bb5435","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl051.jpg","source_page":"https://film-grab.com/2019/01/24/9-songs/","scene":"画面中心可见一辆被强光照亮的马车，车上坐着一名人物。背景完全漆黑，无其他可见环境细节，主体在黑暗中孤立存在。","analysis":"构图极度集中，主体位于画面正中央，周围被大面积黑色负空间包围。人物仅可见上半身轮廓，呈坐姿，身形较小。马车结构在强光下呈现高亮白色，与背景形成极高对比。光线为单一强白光，无色彩层次，仅呈现黑白灰关系。","prompt":"极低分辨率画面，大面积纯黑背景中，画面正中央有一辆被强白光照射的马车。马车轮廓清晰，车轮和车身结构在强光下呈亮白色。车上坐着一名人物，仅可见上半身剪影，呈坐姿。光线从上方或前方直射，形成极高对比度，周围无任何环境细节，仅保留主体亮区与黑暗背景的强烈反差。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:20:52+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/9songsl051.jpg","observed_dimensions":[500,273],"source_thumbnail_dimensions":[500,273],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-bfea4e61fab49eae","origin":"visual"}]};